import base64
import hashlib
import os
import struct
import sys
import zlib
from pathlib import Path

PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"
EXPECTED_WIDTH = 1024
EXPECTED_HEIGHT = 1024
MAX_BYTES = 1_048_576

# ─── Embedded PNG (base64, wrapped ~1000 chars/line) ────────────────────────
# Single live payload: complete base64 of the final candidate (1024x1024,
# 8-bit palette PNG, 70,905 bytes). Decoded and validated before writing.
# Triple-quoted so the wrapped lines need no per-line quotes; b64decode
# ignores the newlines.
_PNG_B64 = """































































































"""


def decode_png():
    """Decode the embedded base64 payload into raw PNG bytes."""
    return base64.b64decode(_PNG_B64)


def validate_png(data):
    """Check the PNG signature, the IHDR dimensions and format (1024x1024,
    8-bit palette), the CRC of every chunk, that no data trails after IEND,
    and that the total size stays under 1 MiB. Returns (width, height).
    Raises ValueError on any problem."""
    if len(data) > MAX_BYTES:
        raise ValueError("image exceeds 1 MiB: %d bytes" % len(data))
    if data[:8] != PNG_SIGNATURE:
        raise ValueError("not a PNG file (bad signature)")
    offset = 8
    width = height = None
    seen_idat = False
    seen_iend = False
    while offset + 8 <= len(data):
        length = struct.unpack(">I", data[offset:offset + 4])[0]
        ctype = data[offset + 4:offset + 8]
        end = offset + 8 + length + 4
        if end > len(data):
            raise ValueError("truncated chunk: %r" % ctype)
        stored_crc = struct.unpack(">I", data[offset + 8 + length:end])[0]
        actual_crc = zlib.crc32(ctype + data[offset + 8:offset + 8 + length])
        if actual_crc != stored_crc:
            raise ValueError("bad CRC in chunk: %r" % ctype)
        if ctype == b"IHDR":
            width, height, depth, colour, comp, filt, inter = struct.unpack(
                ">IIBBBBB", data[offset + 8:offset + 8 + 13])
            if (width, height) != (EXPECTED_WIDTH, EXPECTED_HEIGHT):
                raise ValueError("unexpected size: %dx%d" % (width, height))
            if depth != 8 or colour != 3:
                raise ValueError(
                    "expected 8-bit palette PNG, got depth %d colour %d"
                    % (depth, colour))
            if comp != 0 or filt != 0 or inter != 0:
                raise ValueError("unexpected IHDR compression/filter/interlace")
        if ctype == b"IDAT":
            seen_idat = True
        if ctype == b"IEND":
            seen_iend = True
            if end != len(data):
                raise ValueError("trailing data after IEND")
            break
        offset = end
    if width is None:
        raise ValueError("missing IHDR chunk")
    if not seen_idat:
        raise ValueError("missing IDAT chunk")
    if not seen_iend:
        raise ValueError("missing IEND chunk")
    return width, height


def main(argv):
    data = decode_png()
    width, height = validate_png(data)
    digest = hashlib.sha256(data).hexdigest()
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR")
    if out_dir:
        out_path = Path(out_dir) / "entry.png"
        out_path.parent.mkdir(parents=True, exist_ok=True)
        out_path.write_bytes(data)
    elif len(argv) > 1:
        Path(argv[1]).write_bytes(data)
    else:
        sys.stdout.buffer.write(data)
        sys.stdout.buffer.flush()
    print("entry.png: %dx%d, %d bytes, sha256 %s"
          % (width, height, len(data), digest), file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
